[DataContractAttribute,
SysOperationContractProcessingAttribute(classStr(METNat3040RegisterUpdateUIBuilder),SysOperationDataContractProcessingMode::CreateSeparateUIBuilderForEachContract)]
class METNat3040RegisterUpdateContract implements SysOperationValidatable
{
    NoYesId                 UpdateNat3040;
    MATNat3040ReportNumber  Nat3040Number;
    METExciseRegisterEntry  metExciseRegisterEntry;
     
}

Method.Source:
  /// <summary>
  /// MPJ_5013_ExciseRegisterEntry
  /// Parameters to include NoYesId
  /// </summary>
  /// <param name = "_Noyesid">NoYesId</param>
  /// <returns>UpdateNat3040</returns>
  [
  DataMemberAttribute,
  SysOperationLabelAttribute(literalStr("Update Nat 30/40")),
  SysOperationHelpTextAttribute(literalStr("Update Nat 30/40")),
  SysOperationDisplayOrderAttribute('1')
  ]

  public NoYesId parmUpdateNat3040(NoYesId _Noyesid  = UpdateNat3040)
  {
      UpdateNat3040 = _Noyesid ;
      return UpdateNat3040;
  }

/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// parameter to include NAT3040 Report Number 
/// </summary>
/// <param name = "_Nat3040Number">NAT3040 Report Number </param>
/// <returns>Nat3040Number</returns>

[
DataMemberAttribute,
SysOperationLabelAttribute(literalStr("Nat 30/40 Number")),
SysOperationHelpTextAttribute(literalStr("Nat 30/40 Number")),
SysOperationDisplayOrderAttribute('2')
]
public MATNat3040ReportNumber parmNat3040Number(MATNat3040ReportNumber _Nat3040Number = Nat3040Number)
{
    Nat3040Number = _Nat3040Number;
    return Nat3040Number;
}

    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// </summary>
    /// <returns> isValid true or false </returns>
    public boolean validate()
    {
        boolean isValid = true;

         select firstonly Nat3040ReportNumber from  metExciseRegisterEntry
            where metExciseRegisterEntry.Nat3040ReportNumber == Nat3040Number;

        if(!metExciseRegisterEntry.Nat3040ReportNumber)
        {
            isValid = checkFailed("Enter a valid Nat 30/40 Number");
        }

        return isValid;
    }
